            assert.ok(Array.isArray(res.body.audit_logs));
        });

        it('Can browse with pagination parameters', async function () {
            const res = await request
                .get(localUtils.API.getApiQuery('audit_logs/?limit=5&page=1'))
                .set('Origin', config.get('url'))
                .expect('Content-Type', /json/)
                .expect('Cache-Control', testUtils.cacheRules.private)
                .expect(200);

            localUtils.API.checkResponse(res.body, 'audit_logs');
            assert.ok(Array.isArray(res.body.audit_logs));
            assert.ok(res.body.audit_logs.length <= 5);
        });

        it('Returns 401 when not authenticated', async function () {
            const unauthRequest = supertest.agent(config.get('url'));

            await unauthRequest
                .get(localUtils.API.getApiQuery('audit_logs/'))
                .set('Origin', config.get('url'))
                .expect('Content-Type', /json/)
                .expect(401);
        });
    });

    describe('Read', function () {
        it('Can read a single audit log by id (if any exist)', async function () {
            // First, browse to get an ID if any exist
            const browseRes = await request
                .get(localUtils.API.getApiQuery('audit_logs/'))
                .set('Origin', config.get('url'))
                .expect(200);

            if (browseRes.body.audit_logs && browseRes.body.audit_logs.length > 0) {
                const auditLogId = browseRes.body.audit_logs[0].id;

                const res = await request
                    .get(localUtils.API.getApiQuery(`audit_logs/${auditLogId}/`))
                    .set('Origin', config.get('url'))
                    .expect('Content-Type', /json/)
                    .expect('Cache-Control', testUtils.cacheRules.private)
                    .expect(200);

                localUtils.API.checkResponse(res.body.audit_logs[0], 'audit_log');
                assert.equal(res.body.audit_logs[0].id, auditLogId);
            }
        });

        it('Returns 401 when not authenticated', async function () {
            const unauthRequest = supertest.agent(config.get('url'));

            await unauthRequest
                .get(localUtils.API.getApiQuery('audit_logs/507f1f77bcf86cd799439011/'))
                .set('Origin', config.get('url'))
                .expect('Content-Type', /json/)
                .expect(401);
        });

        it('Returns 404 for non-existent id', async function () {
            await request
                .get(localUtils.API.getApiQuery('audit_logs/507f1f77bcf86cd799439011/'))
                .set('Origin', config.get('url'))
                .expect('Content-Type', /json/)
                .expect(404);
        });
    });
});

