const models = require('../../models');

/** @type {import('@tryghost/api-framework').Controller} */
const controller = {
    docName: 'audit_logs',

    browse: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'page',
            'limit',
            'fields',
            'include',
            'filter'
        ],
        permissions: {
            method: 'browse',
            docName: 'audit_logs'
        },
        query(frame) {
            return models.AuditLog.findPage(frame.options);
        }
    },

    read: {
        headers: {
            cacheInvalidate: false
        },
        options: [
            'include',
            'fields'
        ],
        data: [
            'id'
        ],
        permissions: {
            method: 'read',
            docName: 'audit_logs'
        },
        query(frame) {
            return models.AuditLog.findOne(frame.data, frame.options);
        }
    }
};

module.exports = controller;
